lemma through_original_root {x : T↧.World} (h : T↧.root ≺ x) : x = T.root ∨ (Sum.inr T.root ≺ x) := by
  match x with
  | .inl x =>
    have := T↧.rel_irreflexive _ h;
    contradiction;
  | .inr x =>
    by_cases h : x = T.root;
    . subst h; left; tauto;
    . right; exact FiniteTransitiveTree.SimpleExtension.forth $ T.root_rooted x h;

